// Go: golang.org/x/sync/singleflight
var g singleflight.Group

func GetUser(id string) (User, error) {
    if u, ok := cache.Get(id); ok {
        return u, nil
    }
    v, err, _ := g.Do(id, func() (any, error) {
        u, err := db.LoadUser(id) // chỉ 1 lời gọi cho mỗi id
        if err == nil {
            cache.Set(id, u, ttl+jitter()) // TTL cộng ngẫu nhiên
        }
        return u, err
    })
    if err != nil {
        return User{}, err
    }
    return v.(User), nil
}
